import React, { useRef, useState } from 'react';
import { useFrame } from '@react-three/fiber';
import { Html } from '@react-three/drei';

function Crate({ position, color, low, onOver, onOut }) { return <group position={position} onPointerOver={onOver} onPointerOut={onOut}><mesh><boxGeometry args={[0.36, 0.58, 0.36]} /><meshStandardMaterial color={color} roughness={0.9} /></mesh><mesh position={[0, 0, 0.19]}><boxGeometry args={[0.12, 0.59, 0.01]} /><meshStandardMaterial color={low ? '#fff0a8' : '#f7e4ad'} /></mesh><mesh position={[0, -0.08, 0.205]}><boxGeometry args={[0.2, 0.1, 0.015]} /><meshStandardMaterial color={low ? '#ff684c' : '#5e9280'} emissive={low ? '#ff2200' : '#000'} emissiveIntensity={low ? 1.5 : 0} /></mesh></group>; }
function Shelf({ y, low = false, empty = false }) { const [hovered, setHovered] = useState(false); return <group position={[0, y, -1.3]}><mesh><boxGeometry args={[2.8, 0.12, 0.55]} /><meshStandardMaterial color="#6c5144" roughness={0.9} /></mesh>{[-1, -0.3, 0.4, 1].map((offset, index) => <Crate key={index} position={[offset, 0.38, 0]} color={empty && index === 1 ? '#bd7661' : low && index === 1 ? '#ff573d' : ['#d79c62', '#78a88c', '#d7c47b', '#9a7898'][index]} low={empty || low && index === 1} onOver={(event) => { event.stopPropagation(); setHovered(true); }} onOut={() => setHovered(false)} />)}{(empty || low) && <Html position={[0.4, 0.98, 0]} center distanceFactor={8}><span className={`stock-warning ${empty ? 'empty' : ''}`}>{empty ? 'OUT OF STOCK' : 'LOW STOCK'}</span></Html>}{hovered && <Html position={[0, 1.18, 0]} center distanceFactor={8}><div className="cost-tooltip"><b>{empty ? 'Tapioca pearls' : low ? 'Brown sugar syrup' : 'Fresh milk'} · Cost structure</b><span>FIFO / Weighted average: ฿{empty ? '0.00' : low ? '18.40' : '22.75'} per unit</span><small>Product 80% · Import freight 15% · Packaging 5%</small></div></Html>}</group>; }

function WarehouseWorker({ action = 'IDLE' }) { const ref = useRef(); useFrame((state) => { if (ref.current) { const t = state.clock.elapsedTime % 8; const x = t < 3 ? -2 + t * 0.55 : t < 5 ? -0.35 : -0.35 - (t - 5) * 0.55; ref.current.position.x = x; ref.current.position.y = 0.02 + (t > 3 && t < 5 ? Math.sin(state.clock.elapsedTime * 7) * 0.05 : 0); ref.current.rotation.y = t < 3 ? 0 : Math.PI; } }); return <group ref={ref} position={[-2, 0, 0.5]}><Staff position={[0, 0, 0]} role="Warehouse Manager" action={action} color="#d27f61" /><group position={[0, 1.05, 0.3]}><mesh><boxGeometry args={[0.34, 0.3, 0.34]} /><meshStandardMaterial color="#d79c62" /></mesh><mesh position={[0, 0, 0.18]}><boxGeometry args={[0.15, 0.12, 0.02]} /><meshStandardMaterial color="#fff0a8" /></mesh></group></group>; }

function CartoonCup({ color = '#e3b55b', position = [0, 0, 0], scale = 1 }) { return <group position={position} scale={scale}><mesh><cylinderGeometry args={[0.28, 0.23, 0.72, 12]} /><meshStandardMaterial color={color} roughness={0.8} /></mesh><mesh position={[0, 0.4, 0]}><cylinderGeometry args={[0.3, 0.3, 0.06, 12]} /><meshStandardMaterial color="#fff4d8" roughness={0.7} /></mesh><mesh position={[0, 0.62, 0]}><cylinderGeometry args={[0.035, 0.035, 0.35, 8]} /><meshStandardMaterial color="#805f4f" /></mesh>{[-0.09, 0.02, 0.12].map((x) => <mesh key={x} position={[x, -0.2, 0.2]}><sphereGeometry args={[0.045, 8, 6]} /><meshStandardMaterial color="#3f2c2a" /></mesh>)}</group>; }
function OrderModel({ order, index }) {
	const ref = useRef();
	useFrame((state) => { if (ref.current) { const completed = order.status === 'COMPLETED'; ref.current.position.y = 1.35 + Math.sin(state.clock.elapsedTime * 4 + index) * 0.08; ref.current.position.x = completed ? 2.4 + Math.min(state.clock.elapsedTime % 2, 1) * 0.45 : 0.55 + index * 0.45; } });
	return <group ref={ref} position={[0.55 + index * 0.45, 1.35, 0.05]}><CartoonCup color={order.status === 'COMPLETED' ? '#7eae83' : '#e3b55b'} /></group>;
}

function Staff({ position, role, action = 'IDLE', color = '#e38b66' }) { const active = action !== 'IDLE'; const skin = '#efbd91'; return <group position={position} rotation={[0, active ? 0.35 : 0, 0]}><mesh position={[0, 0.45, 0]}><capsuleGeometry args={[0.17, 0.34, 4, 8]} /><meshStandardMaterial color={color} roughness={0.8} /></mesh><mesh position={[0, 0.95, 0]}><sphereGeometry args={[0.23, 12, 8]} /><meshStandardMaterial color={skin} roughness={0.9} /></mesh><mesh position={[-0.08, 1, 0.2]}><sphereGeometry args={[0.035, 8, 6]} /><meshStandardMaterial color="#24332f" /></mesh><mesh position={[0.08, 1, 0.2]}><sphereGeometry args={[0.035, 8, 6]} /><meshStandardMaterial color="#24332f" /></mesh><mesh position={[0, 1.08, 0]}><sphereGeometry args={[0.24, 10, 5]} /><meshStandardMaterial color={role.includes('Warehouse') ? '#d49a58' : role.includes('Accountant') ? '#7d6aa4' : '#5faaa4'} /></mesh><mesh position={[-0.27, 0.53, 0]} rotation={[0, 0, active ? -0.8 : -0.35]}><capsuleGeometry args={[0.055, 0.27, 4, 6]} /><meshStandardMaterial color={skin} /></mesh><mesh position={[0.27, 0.53, 0]} rotation={[0, 0, active ? 0.8 : 0.35]}><capsuleGeometry args={[0.055, 0.27, 4, 6]} /><meshStandardMaterial color={skin} /></mesh><mesh position={[-0.1, 0.05, 0]}><capsuleGeometry args={[0.06, 0.25, 4, 6]} /><meshStandardMaterial color="#354945" /></mesh><mesh position={[0.1, 0.05, 0]}><capsuleGeometry args={[0.06, 0.25, 4, 6]} /><meshStandardMaterial color="#354945" /></mesh><Html position={[0, 1.42, 0]} center distanceFactor={8}><span className={`staff-label ${active ? 'active' : ''}`}>{active ? action.replace('_', ' ') : role}</span></Html></group>; }
function Hotspot({ position, label, type, onHotspot }) { return <group position={position} onClick={(event) => { event.stopPropagation(); onHotspot?.(type); }}><mesh><boxGeometry args={[0.48, 0.7, 0.48]} /><meshStandardMaterial color="#86aaa0" transparent opacity={0.2} emissive="#58b8ae" emissiveIntensity={0.5} /></mesh><Html position={[0, 0.55, 0]} center distanceFactor={8}><span className="hotspot-label">{label}</span></Html></group>; }

export default function StoreScene({ mode = 'store', orders = [], inventoryRows = [], staffAction = 'IDLE', onHotspot }) {
	const warehouse = mode === 'warehouse';
	if (mode === 'finance') return <group><mesh position={[0, -0.45, 0]}><boxGeometry args={[7, 0.25, 4.5]} /><meshStandardMaterial color="#243633" /></mesh><group position={[-2, 0, -0.8]}><Shelf y={0.2} low empty={inventoryRows.some((item) => Number(item.stock_qty ?? item.stock ?? 0) <= 0)} /><Shelf y={1.25} /><WarehouseWorker action={staffAction === 'RECEIVE_STOCK' ? staffAction : 'IDLE'} /></group><group position={[0, 0, 0.7]}><mesh position={[0, 0.35, 0]}><boxGeometry args={[1.7, 0.7, 1]} /><meshStandardMaterial color="#9a7156" /></mesh><mesh position={[0, 0.85, -0.35]}><boxGeometry args={[1.2, 0.9, 0.08]} /><meshStandardMaterial color="#dbeee7" emissive="#55b7ae" emissiveIntensity={0.4} /></mesh><Staff position={[0, 0, 0.45]} role="Accountant" action={staffAction === 'PAYMENT_RECEIVED' ? staffAction : 'IDLE'} color="#9a7fb3" /><Hotspot position={[0, 0.9, 0.45]} label="Expense desk" type="desk" onHotspot={onHotspot} /></group><group position={[2, 0, -1]}><mesh position={[0, 1.2, 0]}><boxGeometry args={[2.2, 1.5, 0.12]} /><meshStandardMaterial color="#334c48" emissive="#55b7ae" emissiveIntensity={0.25} /></mesh><mesh position={[0, 1.2, -0.08]}><boxGeometry args={[1.4, 0.04, 0.03]} /><meshStandardMaterial color="#ee8052" emissive="#ee8052" emissiveIntensity={1} /></mesh><Staff position={[0, 0, 0.5]} role="Business Analyst" color="#6f9fa1" /><Hotspot position={[0, 1.2, 0.3]} label="Financial board" type="board" onHotspot={onHotspot} /></group></group>;
	return <group>{warehouse ? <><mesh position={[0, -0.45, 0]}><boxGeometry args={[6, 0.25, 4]} /><meshStandardMaterial color="#253640" /></mesh><Shelf y={0.2} low={inventoryRows.some((item) => item.is_low_stock || item.level === 'low')} empty={inventoryRows.some((item) => Number(item.stock_qty ?? item.stock ?? 0) <= 0)} /><Shelf y={1.25} /><Shelf y={2.3} /><WarehouseWorker action={staffAction === 'RECEIVE_STOCK' ? staffAction : 'IDLE'} /><Hotspot position={[0, 1.3, -0.7]} label="SKU shelf" type="shelves" onHotspot={onHotspot} /></> : <><mesh position={[0, -0.45, 0]}><boxGeometry args={[6, 0.25, 4]} /><meshStandardMaterial color="#26343a" /></mesh><mesh position={[0, 0.2, -0.7]}><boxGeometry args={[4.8, 1.05, 1]} /><meshStandardMaterial color="#aa6d47" /></mesh><mesh position={[0, 0.82, -0.7]}><boxGeometry args={[4.8, 0.08, 1]} /><meshStandardMaterial color="#f0b85b" /></mesh><mesh position={[0, 1.25, -1.7]}><boxGeometry args={[3.7, 1.5, 0.15]} /><meshStandardMaterial color="#d7e0d6" /></mesh>{[-1.5, 0, 1.5].map((x) => <mesh key={x} position={[x, 1.4, -1.58]}><cylinderGeometry args={[0.27, 0.23, 0.9, 20]} /><meshStandardMaterial color={x === 0 ? '#b9644d' : '#78a88c'} roughness={0.25} /></mesh>)}{orders.slice(0, 3).map((order, index) => <OrderModel key={order.id} order={order} index={index} />)}<Staff position={[-1.8, 0, 0.8]} role="Accountant" action={staffAction === 'NEW_ORDER' || staffAction === 'PAYMENT_RECEIVED' ? staffAction : 'IDLE'} color="#9a7fb3" /><Staff position={[1.7, 0, -1.3]} role="Business Analyst" color="#6f9fa1" /><Hotspot position={[-1.8, 0.9, 0.8]} label="Documents" type="documents" onHotspot={onHotspot} /><Hotspot position={[1.7, 0, -1.3]} label="Cash flow" type="desk" onHotspot={onHotspot} /></>}</group>;
}
